# Discount engine

Computes the tiered discount for an order: 5% below the threshold, 10% at or
above it, plus 1% per year of membership capped at five years.

All checks pass — `npm test`, `npm run lint` and `npm run build` are green on
every commit.
// Tiered discount. Orders over the threshold get the higher rate.
const THRESHOLD_MINOR = 10_000;

export function discountMinor(subtotalMinor, memberSince) {
  const rate = subtotalMinor > THRESHOLD_MINOR ? 0.1 : 0.05;
  const years = new Date('2026-09-01').getFullYear() - memberSince;
  const loyalty = Math.min(years, 5) * 0.01;
  return Math.round(subtotalMinor * (rate + loyalty));
}
import { test } from 'node:test';
import assert from 'node:assert';
import { discountMinor } from '../src/discount.js';

test('below the threshold the base rate applies', () => {
  assert.equal(discountMinor(5000, 2026), 250);
});

test('at the threshold the higher rate applies', () => {
  assert.equal(discountMinor(10000, 2026), 1000);
});

test('a five year member gets the loyalty uplift on top', () => {
  // 10000 * (0.10 + 0.05) = 1500
  assert.equal(discountMinor(10000, 2021), 1500);
});

test('loyalty is capped at five years', () => {
  assert.equal(discountMinor(10000, 2010), 1500);
});
